1: import React, { useEffect, useState } from "react";
2: import { Button, LoadingIcon } from "@nabstore/styleguide";
3: import useCreateUser from "../../hooks/useCreateUser";
4: import { CreateUserContainer } from "../../components/CreateUserContainer";
5: 
6: const CreateColaborador = () => {
7:   const [nome, setNome] = useState("");
8:   const [email, setEmail] = useState("");
9:   const [emailError, setEmailError] = useState("");
10:   const [senha, setSenha] = useState("");
11:   const [senhaConfirm, setSenhaConfirm] = useState("");
12:   const [senhaError, setSenhaError] = useState("");
13:   const { createUser, isLoading, error } = useCreateUser();
14: 
15:   const handleSubmit = (e) => {
16:     e.preventDefault();
17:     if (senha.length < 6) {
18:       setSenhaError("A senha deve possuir pelo menos 6 caracteres.");
19:       return;
20:     }
21: 
22:     if (senha !== senhaConfirm) {
23:       setSenhaError("Senhas não conferem.");
24:       return;
25:     }
26:     setSenhaError("");
27: 
28:     createUser(nome, email, senha, 2);
29:   };
30: 
31:   useEffect(() => {
32:     if (
33:       error &&
34:       error.response?.status === 400 &&
35:       error.response?.data?.errors[0].message ===
36:         "Usuarios.email must be unique"
37:     ) {
38:       setEmailError("Este e-mail já está cadastrado.");
39:     }
40:   }, [error]);
41: 
42:   return (
43:     <CreateUserContainer className="container">
44:       <div className="d-flex justify-content-center">
45:         <h1>Adição de Colaborador</h1>
46:       </div>
47:       <form onSubmit={handleSubmit}>
48:         <label className="mt-3 mb-1" htmlFor="nome">
49:           Nome Completo
50:         </label>
51:         <input
52:           autoFocus
53:           type="text"
54:           id="nome"
55:           className="form-control"
56:           value={nome}
57:           onChange={(e) => setNome(e.target.value)}
58:         />
59: 
60:         <label className="mt-3 mb-1" htmlFor="email">
61:           E-mail
62:         </label>
63:         <input
64:           id="email"
65:           type="email"
66:           className={
67:             emailError === "" ? "form-control" : "form-control is-invalid"
68:           }
69:           value={email}
70:           onChange={(e) => setEmail(e.target.value)}
71:         />
72:         <div className="invalid-feedback">{emailError}</div>
73: 
74:         <label className="mt-3 mb-1" htmlFor="senha">
75:           Senha
76:         </label>
77:         <input
78:           type="password"
79:           id="senha"
80:           className={
81:             senhaError === "" ? "form-control" : "form-control is-invalid"
82:           }
83:           value={senha}
84:           onChange={(e) => setSenha(e.target.value)}
85:         />
86: 
87:         <label className="mt-3 mb-1" htmlFor="confirmSenha">
88:           Confirme a senha
89:         </label>
90:         <input
91:           type="password"
92:           id="confirmSenha"
93:           className={
94:             senhaError === "" ? "form-control" : "form-control is-invalid"
95:           }
96:           value={senhaConfirm}
97:           onChange={(e) => setSenhaConfirm(e.target.value)}
98:         />
99:         <div className="invalid-feedback">{senhaError}</div>
100: 
101:         <Button.Secondary
102:           disabled={
103:             nome === "" || email === "" || senha === "" || senhaConfirm == ""
104:           }
105:         >
106:           {isLoading ? <LoadingIcon.Oval stroke="#2f2f2f" /> : "Criar"}
107:         </Button.Secondary>
108:       </form>
109:     </CreateUserContainer>
110:   );
111: };
112: 
113: export default CreateColaborador;

