12: const Checkout = ({ cleanCartAction }) => {
13:   const { user, cart } = useSelector((state) => ({
14:     cart: state.cart,
15:     user: state.user,
16:   }));
17:   const [total, setTotal] = useState(0);
18:   const dispatch = useDispatch();
19:   const navigate = useNavigate();
20:   const { createCompra, data, isLoading, error } = useCreateCompra();
21: 
22:   useEffect(() => {
23:     setTotal(
24:       cart.produtos.reduce(
25:         (prev, actual) => prev + actual.qtd * actual.precoUnit,
26:         0
27:       )
28:     );
29:   }, [cart]);
30: 
31:   useEffect(() => {
32:     if (data) {
33:       const args = {
34:         message: "OBRIGADO",
35:         description: "Compra realizada com sucesso!",
36:         duration: 2,
37:       };
38:       notification.success(args);
39:       dispatch(cleanCartAction());
40:       navigate(routes.HOME);
